package com.onlinehomework.grading.api;
import com.onlinehomework.grading.api.GradeDtos.*; import com.onlinehomework.grading.application.GradingService; import com.onlinehomework.identity.api.AuthenticatedActor; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1") @PreAuthorize("hasRole('TEACHER')") public class GradingController { private final GradingService s; public GradingController(GradingService s){this.s=s;} @PostMapping("/submissions/{submissionId}/grades") @ResponseStatus(HttpStatus.CREATED) public GradeResponse create(@AuthenticationPrincipal Jwt j,@PathVariable UUID submissionId,@Valid @RequestBody CreateGradeRequest r){return s.create(AuthenticatedActor.from(j).userId(),submissionId,r);} @GetMapping("/submissions/{submissionId}/grades") public List<GradeResponse> list(@AuthenticationPrincipal Jwt j,@PathVariable UUID submissionId){return s.list(AuthenticatedActor.from(j).userId(),submissionId);} @PostMapping("/grades/{gradeId}/publish") public GradeResponse publish(@AuthenticationPrincipal Jwt j,@PathVariable UUID gradeId){return s.publish(AuthenticatedActor.from(j).userId(),gradeId);} }
